-- ==========================================================
-- BẢN DỮ LIỆU PHÁT TRIỂN CŨ - KHÔNG DÙNG CHO PRODUCTION
-- Các cửa hàng, giá, đánh giá và chính sách bên dưới chưa được đối soát đầy đủ.
-- Runtime hiện dùng JSON; xem HOSTING.md trước khi triển khai.
-- ==========================================================

CREATE DATABASE IF NOT EXISTS `fixnear_db` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `fixnear_db`;

-- 1. Bảng USERS
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(100) NOT NULL,
  `email` VARCHAR(150) NOT NULL UNIQUE,
  `password` VARCHAR(255) NOT NULL,
  `role` ENUM('admin', 'user') DEFAULT 'user',
  `phone` VARCHAR(50) DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Bảng SHOPS
DROP TABLE IF EXISTS `shops`;
CREATE TABLE `shops` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(200) NOT NULL,
  `address` VARCHAR(255) NOT NULL,
  `ward` VARCHAR(100) NOT NULL,
  `district` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(50) NOT NULL,
  `opening_hours` VARCHAR(100) DEFAULT '08:00 - 21:00',
  `map_url` TEXT,
  `latitude` DECIMAL(10, 6) DEFAULT 10.853800,
  `longitude` DECIMAL(10, 6) DEFAULT 106.626300,
  `description` TEXT,
  `google_rating` DECIMAL(2, 1) DEFAULT NULL,
  `google_reviews_count` INT DEFAULT NULL,
  `devices` VARCHAR(100) DEFAULT 'laptop,phone',
  `is_verified` TINYINT(1) DEFAULT 0,
  `allows_onsite_watch` TINYINT(1) DEFAULT 0,
  `requires_component_signing` TINYINT(1) DEFAULT 0,
  `student_discount` VARCHAR(255) DEFAULT NULL,
  `image` TEXT,
  `website` VARCHAR(255) DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Bảng SERVICES
DROP TABLE IF EXISTS `services`;
CREATE TABLE `services` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(150) NOT NULL,
  `device_type` VARCHAR(50) NOT NULL,
  `devices` VARCHAR(100) DEFAULT NULL,
  `icon` VARCHAR(50) DEFAULT 'tool',
  `description` TEXT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. Bảng BOOKINGS (Lịch hẹn sửa chữa & yêu cầu báo giá)
DROP TABLE IF EXISTS `bookings`;
CREATE TABLE `bookings` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `shop_id` INT NOT NULL DEFAULT 1,
  `customer_name` VARCHAR(100) NOT NULL,
  `customer_email` VARCHAR(150) DEFAULT NULL,
  `customer_phone` VARCHAR(20) NOT NULL,
  `device_type` VARCHAR(100) NOT NULL,
  `issue_description` TEXT,
  `preferred_date` DATE NOT NULL,
  `preferred_time` VARCHAR(100) NOT NULL,
  `status` ENUM('pending', 'contacted', 'confirmed', 'completed', 'cancelled') DEFAULT 'pending',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 5. Bảng REVIEWS
DROP TABLE IF EXISTS `reviews`;
CREATE TABLE `reviews` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `shop_id` INT NOT NULL,
  `user_id` INT DEFAULT NULL,
  `user_name` VARCHAR(100) NOT NULL,
  `rating` INT NOT NULL,
  `device_name` VARCHAR(100) DEFAULT NULL,
  `service_repaired` VARCHAR(150) DEFAULT NULL,
  `comment` TEXT NOT NULL,
  `is_hidden` TINYINT(1) DEFAULT 0,
  `admin_reply` TEXT DEFAULT NULL,
  `admin_reply_at` DATETIME DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 6. Bảng WRONG_INFO_REPORTS (Báo cáo thông tin sai)
DROP TABLE IF EXISTS `wrong_info_reports`;
CREATE TABLE `wrong_info_reports` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `shop_id` INT NOT NULL,
  `reporter_name` VARCHAR(100) NOT NULL,
  `reporter_phone` VARCHAR(50) DEFAULT NULL,
  `reason` VARCHAR(200) NOT NULL,
  `details` TEXT,
  `status` ENUM('pending', 'resolved') DEFAULT 'pending',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dữ liệu dịch vụ & lỗi
INSERT INTO `services` (`id`, `name`, `device_type`, `devices`, `icon`, `description`) VALUES
(1, 'Thay màn hình hiển thị', 'all', 'phone,tablet,laptop,mac,smartwatch', 'monitor', 'Thay cụm màn hình nguyên bộ khi bị sọc màn, chảy mực, liệt cảm ứng hoặc tối đen.'),
(2, 'Ép mặt kính / Kính cảm ứng', 'phone', 'phone,tablet,smartwatch', 'copy', 'Màn hình cảm ứng và hiển thị bình thường, chỉ bị nứt vỡ lớp kính bảo vệ bên ngoài.'),
(3, 'Thay pin dung lượng cao / Pin Zin', 'all', 'phone,tablet,laptop,mac,smartwatch', 'battery-charging', 'Khắc phục pin chai dưới 80%, phồng pin bung nắp lưng, sạc không vào hoặc sập nguồn.'),
(4, 'Sửa chân sạc / Cổng kết nối', 'all', 'phone,tablet,laptop,mac,smartwatch,pc', 'zap', 'Khắc phục lỏng chân Type-C, Lightning, DC Jack, cắm sạc chập chờn hoặc không nhận điện.'),
(5, 'Cấp cứu máy vô nước / Rớt nước', 'all', 'phone,tablet,laptop,mac,smartwatch', 'droplet', 'Sấy khô bằng sóng siêu âm chuyên dụng, tẩy rỉ sét chân IC và tiếp xúc bo mạch khi máy rớt nước.'),
(6, 'Sửa mất nguồn / Lỗi Mainboard', 'all', 'phone,tablet,laptop,mac,smartwatch,pc', 'power', 'Khắc phục chết IC nguồn, chập tụ, kích nguồn không chạy, đèn nhấp nháy hoặc treo logo.'),
(7, 'Thay camera trước / sau', 'phone', 'phone,tablet,laptop,mac', 'camera', 'Camera bị đục mờ, rung giật chống rung OIS, đốm tím, vỡ kính camera ngoài.'),
(8, 'Loa trong / Loa ngoài rè', 'all', 'phone,tablet,laptop,mac,smartwatch', 'volume-x', 'Loa thoại nhỏ xíu, loa chuông rè chói tai khi nghe nhạc, xem phim hoặc đàm thoại.'),
(9, 'Hỏng Micro (Nói không nghe)', 'all', 'phone,tablet,laptop,mac,smartwatch', 'mic-off', 'Gọi điện thoại, quay video hoặc gửi tin nhắn thoại đối phương không nghe được tiếng.'),
(10, 'Bàn phím liệt / Kẹt nút bấm', 'laptop', 'laptop,mac,pc', 'keyboard', 'Thay bàn phím laptop mới chính hãng, xử lý liệt phím, kẹt phím, chập nhảy chữ liên tục.'),
(11, 'Chuột cảm ứng / Trackpad', 'laptop', 'laptop,mac', 'mouse-pointer', 'Thay bàn rê chuột cảm ứng Trackpad bị đơ, loạn cảm ứng hoặc kẹt cứng không bấm được.'),
(12, 'Sửa gãy bản lề / Vỏ khung sườn', 'all', 'laptop,mac,phone,tablet', 'tool', 'Hàn gia cố chân ốc bản lề laptop, thay vỏ mặt A/B/C/D, thay sườn máy điện thoại cấn móp.'),
(13, 'Nâng cấp ổ cứng SSD siêu tốc', 'laptop', 'laptop,mac,pc', 'hard-drive', 'Nâng cấp SSD NVMe / SATA 256GB/512GB/1TB/2TB giúp khởi động máy chỉ trong 5 giây.'),
(14, 'Nâng cấp bộ nhớ RAM', 'laptop', 'laptop,mac,pc', 'cpu', 'Nâng thêm RAM DDR4/DDR5 8GB, 16GB, 32GB giúp máy chạy mượt đa nhiệm, mở nhiều tab Chrome & code.'),
(15, 'Vệ sinh máy & Tra keo tản nhiệt', 'laptop', 'laptop,mac,pc', 'wind', 'Làm sạch bụi bẩn, tra keo tản nhiệt gấu MX-4/Kryonaut làm mát chip, xử lý quạt kêu to.'),
(16, 'Cài Hệ điều hành & Phần mềm', 'laptop', 'laptop,mac,pc,phone', 'monitor', 'Cài Win 10/11 sạch, cài macOS Sonoma/Sequoia, cài trọn bộ Office, Photoshop, VS Code, đồ họa.'),
(17, 'Cứu dữ liệu ổ cứng & Bo mạch', 'all', 'laptop,mac,pc,phone,tablet', 'database', 'Phục hồi dữ liệu cá nhân, đồ án, tài liệu quan trọng từ máy chết nguồn, vô nước, ổ cứng bad.'),
(18, 'Kiểm tra chẩn đoán toàn diện', 'all', 'phone,tablet,laptop,mac,smartwatch,pc', 'search', 'Kỹ thuật viên đo đạc linh kiện, test chuyên sâu mọi chức năng & báo giá công khai miễn phí.');

-- Dữ liệu 68 cửa hàng uy tín (17 quận nội thành TP.HCM)
INSERT INTO `shops` (`id`, `name`, `address`, `ward`, `district`, `phone`, `opening_hours`, `map_url`, `latitude`, `longitude`, `description`, `google_rating`, `google_reviews_count`, `devices`, `is_verified`, `allows_onsite_watch`, `requires_component_signing`, `student_discount`, `image`, `website`) VALUES
(1, 'Điện Thoại Vui - 136 Nguyễn Thái Học Q.1', '136 Nguyễn Thái Học, Phường Phạm Ngũ Lão, Quận 1, TP.HCM', 'Phạm Ngũ Lão', 'Quận 1', '1800 2064', '08:00 - 21:00 (Cả CN & Lễ)', 'https://www.google.com/maps/search/?api=1&query=%C4%90i%E1%BB%87n%20Tho%E1%BA%A1i%20Vui%20-%20136%20Nguy%E1%BB%85n%20Th%C3%A1i%20H%E1%BB%8Dc%20Q.1%20136%20Nguy%E1%BB%85n%20Th%C3%A1i%20H%E1%BB%8Dc%2C%20Ph%C6%B0%E1%BB%9Dng%20Ph%E1%BA%A1m%20Ng%C5%A9%20L%C3%A3o%2C%20Qu%E1%BA%ADn%201%2C%20TP.HCM', 10.7665, 106.692, 'Hệ thống sửa chữa điện thoại & laptop hàng đầu Việt Nam. Quy trình minh bạch, báo giá trước khi sửa, cam kết linh kiện chính hãng, bảo hành dài hạn.', 4.9, 3850, 'laptop,phone,mac,tablet', 1, 1, 1, 'Chương trình Back to School: Miễn phí vệ sinh + giảm giá tiền công (xuất trình thẻ SV)', 'https://images.unsplash.com/photo-1597872200969-2b65d56bd16b?w=600&auto=format&fit=crop&q=80', 'https://dienthoaivui.com.vn'),
(2, 'Viện Di Động - 73 Trần Quang Khải Q.1', '73 Trần Quang Khải, Phường Tân Định, Quận 1, TP.HCM', 'Tân Định', 'Quận 1', '0364 769 999', '08:00 - 21:00 (Cả CN & Lễ)', 'https://www.google.com/maps/search/?api=1&query=Vi%E1%BB%87n%20Di%20%C4%90%E1%BB%99ng%20-%2073%20Tr%E1%BA%A7n%20Quang%20Kh%E1%BA%A3i%20Q.1%2073%20Tr%E1%BA%A7n%20Quang%20Kh%E1%BA%A3i%2C%20Ph%C6%B0%E1%BB%9Dng%20T%C3%A2n%20%C4%90%E1%BB%8Bnh%2C%20Qu%E1%BA%ADn%201%2C%20TP.HCM', 10.7895, 106.6905, 'Trung tâm bảo hành & sửa chữa ủy quyền Apple tại Q.1. Kỹ thuật viên chuyên nghiệp, linh kiện zin bóc máy, quy trình ký tên linh kiện 100%.', 4.9, 1250, 'phone,mac,tablet,laptop', 1, 1, 1, '', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=600&auto=format&fit=crop&q=80', 'https://viendidong.com'),
(3, 'Bảo Hành One - 195 Nguyễn Thái Học Q.1', '195 Nguyễn Thái Học, Phường Phạm Ngũ Lão, Quận 1, TP.HCM', 'Phạm Ngũ Lão', 'Quận 1', '1800 1236', '08:00 - 21:00 (Cả CN & Lễ)', 'https://www.google.com/maps/search/?api=1&query=B%E1%BA%A3o+H%C3%A0nh+One+195+Nguy%E1%BB%85n+Th%C3%A1i+H%E1%BB%8Dc+Qu%E1%BA%ADn+1+TP.HCM', 10.7645, 106.6912, 'Trung tâm dịch vụ sửa chữa laptop, điện thoại, máy tính bảng uy tín lâu năm tại Quận 1. Đội ngũ kỹ thuật viên giàu kinh nghiệm, linh kiện chính hãng, bảo hành chu đáo.', 4.8, 1420, 'laptop,phone,mac,tablet', 1, 1, 1, 'Giảm 10% phí dịch vụ cho học sinh, sinh viên khi xuất trình thẻ', 'https://images.unsplash.com/photo-1517077304055-6e89abbf09b0?w=600&auto=format&fit=crop&q=80', 'https://baohanhone.com'),
(4, 'Bệnh Viện Điện Thoại Laptop 24h - Tân Định Q.1', '249-251 Trần Quang Khải, Phường Tân Định, Quận 1, TP.HCM', 'Tân Định', 'Quận 1', '1900 0213', '08:00 - 21:00 (Cả CN & Lễ)', 'https://www.google.com/maps/search/?api=1&query=B%E1%BB%87nh%20Vi%E1%BB%87n%20%C4%90i%E1%BB%87n%20Tho%E1%BA%A1i%20Laptop%2024h%20-%20T%C3%A2n%20%C4%90%E1%BB%8Bnh%20Q.1%20249-251%20Tr%E1%BA%A7n%20Quang%20Kh%E1%BA%A3i%2C%20Ph%C6%B0%E1%BB%9Dng%20T%C3%A2n%20%C4%90%E1%BB%8Bnh%2C%20Qu%E1%BA%ADn%201%2C%20TP.HCM', 10.7918, 106.6912, 'Chuỗi sửa chữa lớn nhất Việt Nam với 20+ chi nhánh. Xuất hóa đơn VAT, cam kết hoàn tiền 100% nếu không hài lòng. Hotline 24/7.', 4.7, 1480, 'laptop,phone,mac,tablet,pc', 1, 1, 1, '', 'https://images.unsplash.com/photo-1563770660941-20978e870e26?w=600&auto=format&fit=crop&q=80', 'https://chamsocdidong.com'),
(5, 'Sài Gòn Số - CN2 Nguyễn Phúc Nguyên Q.3', '11 Nguyễn Phúc Nguyên, Phường 10, Quận 3, TP.HCM', 'Phường 10', 'Quận 3', '0909 186 168', 'T2-T7 08:00 - 19:30, CN 08:00 - 17:00', 'https://www.google.com/maps/search/?api=1&query=S%C3%A0i%20G%C3%B2n%20S%E1%BB%91%20-%20CN2%20Nguy%E1%BB%85n%20Ph%C3%BAc%20Nguy%C3%AAn%20Q.3%2011%20Nguy%E1%BB%85n%20Ph%C3%BAc%20Nguy%C3%AAn%2C%20Ph%C6%B0%E1%BB%9Dng%2010%2C%20Qu%E1%BA%ADn%203%2C%20TP.HCM', 10.7788, 106.6825, 'Trung tâm sửa chữa chuyên nghiệp với đánh giá 4.9★ trên Google Maps (2.580 reviews). Báo giá minh bạch, linh kiện chất lượng cao.', 4.9, 2580, 'laptop,phone,mac,tablet,pc', 1, 1, 1, '', 'https://images.unsplash.com/photo-1580820267682-426da823b514?w=600&auto=format&fit=crop&q=80', 'https://saigonso.com'),
(6, 'Viện Di Động - 608 Lê Văn Sỹ Q.3', '608 Lê Văn Sỹ, Phường 14, Quận 3, TP.HCM', 'Phường 14', 'Quận 3', '1800 6729', '08:00 - 21:00 (Cả CN & Lễ)', 'https://www.google.com/maps/search/?api=1&query=Vi%E1%BB%87n%20Di%20%C4%90%E1%BB%99ng%20-%20608%20L%C3%AA%20V%C4%83n%20S%E1%BB%B9%20Q.3%20608%20L%C3%AA%20V%C4%83n%20S%E1%BB%B9%2C%20Ph%C6%B0%E1%BB%9Dng%2014%2C%20Qu%E1%BA%ADn%203%2C%20TP.HCM', 10.7915, 106.672, 'Chi nhánh Viện Di Động trên trục đường Lê Văn Sỹ sầm uất. Sửa chữa iPhone, iPad, MacBook chuyên sâu, bảo hành ủy quyền Apple.', 4.9, 1250, 'phone,mac,tablet,laptop', 1, 1, 1, '', 'https://images.unsplash.com/photo-1591488320449-011701bb6704?w=600&auto=format&fit=crop&q=80', 'https://viendidong.com'),
(7, 'FASTCARE - 580 Cách Mạng Tháng 8 Q.3', '580 Cách Mạng Tháng 8, Phường 11, Quận 3, TP.HCM', 'Phường 11', 'Quận 3', '1800 2057', '08:00 - 21:30 (Cả CN & Lễ)', 'https://www.google.com/maps/search/?api=1&query=FASTCARE%20-%20580%20C%C3%A1ch%20M%E1%BA%A1ng%20Th%C3%A1ng%208%20Q.3%20580%20C%C3%A1ch%20M%E1%BA%A1ng%20Th%C3%A1ng%208%2C%20Ph%C6%B0%E1%BB%9Dng%2011%2C%20Qu%E1%BA%ADn%203%2C%20TP.HCM', 10.783, 106.6715, 'Chi nhánh FASTCARE trên trục CMT8 trung tâm Q.3. Sửa lấy liền trong 30-60 phút, đặt lịch online tiện lợi qua website.', 4.7, 1350, 'laptop,phone,mac,tablet', 1, 1, 1, '', 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=600&auto=format&fit=crop&q=80', 'https://fastcare.vn'),
(8, 'Sửa Chữa Laptop 24h - CMT8 Q.3', '283/47 Cách Mạng Tháng 8, Phường 12, Quận 3, TP.HCM', 'Phường 12', 'Quận 3', '1800 6024', '08:00 - 20:00 (T2-CN)', 'https://www.google.com/maps/search/?api=1&query=S%E1%BB%ADa%20Ch%E1%BB%AFa%20Laptop%2024h%20-%20CMT8%20Q.3%20283/47%20C%C3%A1ch%20M%E1%BA%A1ng%20Th%C3%A1ng%208%2C%20Ph%C6%B0%E1%BB%9Dng%2012%2C%20Qu%E1%BA%ADn%203%2C%20TP.HCM', 10.776, 106.678, 'Hệ thống sửa chữa laptop chuyên nghiệp hàng đầu. Chuyên xử lý lỗi mainboard, thay màn hình, nâng cấp SSD/RAM cho mọi dòng laptop.', 4.7, 1480, 'laptop,mac,pc', 1, 1, 1, '', 'https://images.unsplash.com/photo-1588702547919-26089e690ecc?w=600&auto=format&fit=crop&q=80', 'https://suachualaptop24h.com'),
