INSERT INTO `reviews` (`id`, `shop_id`, `user_id`, `user_name`, `rating`, `device_name`, `service_repaired`, `comment`, `is_hidden`, `admin_reply`, `admin_reply_at`, `created_at`) VALUES
(1, 1, 2, 'Nguyễn Văn Nam', 5, 'Laptop Asus TUF F15', 'Thay pin laptop', 'Mình đi thay pin ở Điện Thoại Vui 136 Nguyễn Thái Học, thợ mở máy cho mình xem tận mắt, pin mới nguyên seal. Thay xong test phần mềm BatteryReport báo pin 100% dung lượng. Nhân viên tư vấn nhiệt tình, có phiếu bảo hành 6 tháng.', 0, 'FixNear chân thành cảm ơn bạn Nam đã chia sẻ trải nghiệm thực tế! Tiêu chuẩn cho khách ngồi xem trực tiếp và kiểm tra dung lượng pin trước khi bàn giao là quy định bắt buộc đối với tất cả đối tác được công bố trên nền tảng FixNear.', '2026-09-15 14:15:00', '2026-09-15 10:30:00'),
(2, 2, 3, 'Trần Minh Hoàng', 5, 'iPhone 12 Pro', 'Thay pin điện thoại', 'Bên Viện Di Động 73 Trần Quang Khải làm việc cực kỳ chuyên nghiệp. Báo giá trên web bao nhiêu tới nơi thu đúng bấy nhiêu, không vẽ thêm tiền công. Có phiếu bảo hành điện tử qua SĐT, lấy máy sau 30 phút.', 0, 'Cảm ơn bạn Hoàng đã phản hồi tích cực! FixNear luôn giám sát chặt chẽ tính chuẩn xác của bảng giá niêm yết để bảo đảm khách hàng không bao giờ bị phát sinh phụ phí ẩn.', '2026-09-16 18:20:00', '2026-09-16 15:45:00'),
(3, 3, 4, 'Lê Thị Lan Anh', 5, 'MacBook Pro M1', 'Vệ sinh máy & Tra keo tản nhiệt', 'Tiệm Bảo Hành One 195 Nguyễn Thái Học vệ sinh rất kỹ, thợ tháo từng cánh quạt ra lau sạch bụi rồi tra keo gấu xịn. Máy mình từ 85 độ C lúc render video giảm còn 65 độ. Được xuất trình thẻ sinh viên giảm 10% phí dịch vụ rất hài lòng!', 0, 'Cảm ơn bạn Lan Anh đã tin tưởng sử dụng dịch vụ tại đối tác của FixNear!', '2026-09-17 19:00:00', '2026-09-17 17:20:00'),
(4, 4, 2, 'Nguyễn Văn Nam', 5, 'Samsung Galaxy A53', 'Thay mặt kính / Ép kính', 'Bệnh Viện Điện Thoại Laptop 24h Tân Định làm việc rất chuẩn mực, cho ký tên lên mainboard và màn hình trước khi ép kính. Lấy máy sau 40 phút, cảm ứng mượt mà và màn hình trong veo.', 0, NULL, NULL, '2026-09-18 11:15:00'),
(5, 15, 3, 'Trần Minh Hoàng', 5, 'Laptop Lenovo ThinkPad', 'Cài Windows & Phần mềm văn phòng', 'iCare Center Hùng Vương hỗ trợ rất nhanh nhẹn và am hiểu kỹ thuật! Cài Win sạch chuẩn UEFI, kích hoạt bản quyền, cài đầy đủ phần mềm văn phòng, đồ họa và tối ưu tốc độ khởi động chỉ 15 giây. 10 sao cho độ nhiệt tình!', 0, NULL, NULL, '2026-09-19 19:10:00'),
(6, 38, 4, 'Lê Thị Lan Anh', 5, 'Laptop Dell Inspiron 5515', 'Thay pin laptop', 'Chi nhánh FASTCARE Tô Ký gần trường FPT Polytechnic, thợ mở máy cho mình xem tận mắt, pin mới nguyên seal. Thay xong test phần mềm BatteryReport báo pin 100% dung lượng. Sinh viên được hỗ trợ nhiệt tình!', 0, NULL, NULL, '2026-09-20 14:00:00'),
(7, 39, 2, 'Nguyễn Văn Nam', 5, 'Laptop Asus ROG', 'Bàn phím liệt / Kẹt nút bấm', 'Bệnh viện Laptop ZIN Tô Ký thay phím zin gõ cực êm, thợ thao tác nhanh trong 30 phút, giá chuẩn theo khung tham khảo trên FixNear không phát sinh thêm chi phí.', 0, NULL, NULL, '2026-09-21 09:30:00');
